@layer components {
  :where([data-control-family="toast"][data-slot="root"]) {
    --toast-radius: var(--radius-popover);
    --toast-background: var(--popover);
    --toast-border-color: var(--border);
    --toast-border-width: 1px;
    --toast-shadow: var(--shadow-pop);
    --_toast-transform-origin: bottom;
    border-radius: var(--toast-radius);
    --_toast-swipe-x: var(--toast-swipe-movement-x);
    --_toast-swipe-y: var(--toast-swipe-movement-y);
    --_toast-stack-index: var(--toast-index);
    background: var(--toast-background);
    box-shadow: inset 0 0 0 var(--toast-border-width) var(--toast-border-color), var(--toast-shadow);
    color: var(--popover-foreground);
    outline: none;
    -webkit-backdrop-filter: blur(var(--backdrop-blur-popover));
    backdrop-filter: blur(var(--backdrop-blur-popover));
    transform-origin: var(--_toast-transform-origin);
    transform: translateX(var(--_toast-swipe-x))
      translateY(calc(var(--_toast-swipe-y) - (var(--_toast-stack-index) * var(--peek)) - (var(--shrink) * var(--height))))
      scale(var(--scale));
    transition:
      transform var(--duration-slow) var(--ease-emphasized),
      opacity var(--duration-slow) var(--ease-standard),
      height var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="toast"][data-slot="root"]:where([data-ending-style], [data-limited])) {
    opacity: 0;
  }

  :where([data-control-family="toast"][data-slot="root"][data-expanded]) {
    transform: translateX(var(--_toast-swipe-x)) translateY(var(--offset-y));
  }

  :where([data-control-family="toast"][data-slot="root"][data-starting-style]),

  :where(
    [data-control-family="toast"][data-slot="root"][data-ending-style]:not([data-limited]):not([data-swipe-direction])
  ) {
    transform: translateY(150%);
  }

  :where([data-control-family="toast"][data-slot="root"][data-ending-style][data-swipe-direction="down"]) {
    transform: translateY(calc(var(--_toast-swipe-y) + 150%));
  }

  :where([data-control-family="toast"][data-slot="root"][data-ending-style][data-swipe-direction="up"]) {
    transform: translateY(calc(var(--_toast-swipe-y) - 150%));
  }

  :where([data-control-family="toast"][data-slot="root"][data-ending-style][data-swipe-direction="left"]) {
    transform: translateX(calc(var(--_toast-swipe-x) - 150%)) translateY(var(--offset-y));
  }

  :where([data-control-family="toast"][data-slot="root"][data-ending-style][data-swipe-direction="right"]) {
    transform: translateX(calc(var(--_toast-swipe-x) + 150%)) translateY(var(--offset-y));
  }

  :where([data-control-family="toast"][data-slot="content"]) {
    transition: opacity var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="toast"][data-slot="content"][data-behind]) {
    opacity: 0;
  }

  :where([data-control-family="toast"][data-slot="content"][data-expanded]) {
    opacity: 1;
  }

  :where([data-control-family="toast"][data-slot="indicator"]) {
    --_toast-indicator-background: var(--foreground);
    border-radius: 9999px;
    background: var(--_toast-indicator-background);
  }

  :where([data-control-family="toast"][data-type="error"] [data-slot="indicator"]) {
    --_toast-indicator-background: var(--destructive);
  }

  :where([data-control-family="toast"][data-slot="title"]) {
    font-size: var(--text-body);
    font-weight: 600;
    line-height: 1;
    letter-spacing: -0.025em;
  }

  :where([data-control-family="toast"][data-slot="description"]) {
    color: var(--muted-foreground);
    font-size: var(--text-body);
  }

  :where([data-control-family="toast"]:where([data-slot="action"], [data-slot="close"])) {
    --_toast-control-foreground: var(--foreground);
    border-radius: var(--radius-control);
    background: transparent;
    color: var(--_toast-control-foreground);
    outline: none;
    transition:
      color var(--duration-fast) var(--ease-standard),
      background-color var(--duration-fast) var(--ease-standard),
      opacity var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="toast"]:where([data-slot="action"], [data-slot="close"]):hover) {
    background: oklch(from var(--foreground) l c h / 0.06);
  }

  :where([data-control-family="toast"]:where([data-slot="action"], [data-slot="close"]):focus-visible) {
    box-shadow: 0 0 0 2px var(--focus-ring);
  }

  :where([data-control-family="toast"][data-slot="action"]) {
    box-shadow: inset 0 0 0 1px var(--border);
  }

  :where([data-control-family="toast"][data-slot="close"]) {
    --_toast-control-foreground: var(--muted-foreground);
    opacity: 0.7;
  }

  :where([data-control-family="toast"][data-slot="close"]:hover) {
    opacity: 1;
  }

  :where([data-control-family="toast"][data-slot="viewport"]) {
    --_toast-viewport-outline: none;
    outline-style: var(--_toast-viewport-outline);
  }
}

@property --toast-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --toast-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --toast-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --toast-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --toast-shadow {
  syntax: "*";
  inherits: true;
}

"use client";

import { Toast as ToastPrimitive } from "@base-ui/react/toast";
import type { ReactNode } from "react";
import type { ToasterProps } from "@/components/control-ui/contracts";
import { cn } from "@/components/control-ui/lib/cn";
import { skinEffects, skinId } from "@/components/control-ui/skin";

// Base UI's Toast manager, not sonner, behind module-level manager so `toast()` stays callable anywhere.

// shared by imperative `toast()` API and the <Toaster /> Provider
export const toastManager = ToastPrimitive.createToastManager();

type ToastOptions = Omit<Parameters<typeof toastManager.add>[0], "title">;

function withType(type: string) {
  return (title: ReactNode, options?: ToastOptions) => toastManager.add({ title, type, ...options });
}

// callable object, so sonner-shaped surface holds
export const toast = Object.assign((title: ReactNode, options?: ToastOptions) => toastManager.add({ title, ...options }), {
  success: withType("success"),
  error: withType("error"),
  warning: withType("warning"),
  info: withType("info"),
  message: (title: ReactNode, options?: ToastOptions) => toastManager.add({ title, ...options }),
  promise: (...args: Parameters<typeof toastManager.promise>) => toastManager.promise(...args),
  dismiss: (id?: string) => toastManager.close(id),
});

// lets custom viewport read live toast list inside Provider
export const useToast = ToastPrimitive.useToastManager;

function ToastList({
  rootStyle,
  indicatorStyle,
  actionStyle,
  closeStyle,
}: Pick<ToasterProps, "rootStyle" | "indicatorStyle" | "actionStyle" | "closeStyle">) {
  const { toasts } = ToastPrimitive.useToastManager();
  return toasts.map((entry) => {
    return (
      <ToastPrimitive.Root
        key={entry.id}
        toast={entry}
        data-control-ui="toast"
        data-control-family="toast"
        data-type={entry.type ?? "message"}
        style={rootStyle}
        data-slot="root"
        data-surface="floating"
        className={cn(
          "[--gap:0.75rem] [--peek:0.75rem] [--scale:calc(max(0,1-(var(--toast-index)*0.1)))] [--shrink:calc(1-var(--scale))] [--height:var(--toast-frontmost-height,var(--toast-height))] [--offset-y:calc(var(--toast-offset-y)*-1+calc(var(--toast-index)*var(--gap)*-1)+var(--toast-swipe-movement-y))]",
          "absolute right-0 bottom-0 left-auto z-[calc(1000-var(--toast-index))] h-[var(--height)] w-full select-none data-[expanded]:h-[var(--toast-height)]",
          "after:absolute after:top-full after:left-0 after:h-[calc(var(--gap)+1px)] after:w-full after:content-['']",
        )}
      >
        <ToastPrimitive.Content
          data-control-ui="toast"
          data-control-family="toast"
          data-slot="content"
          className="flex items-start gap-3 p-3"
        >
          {entry.type && entry.type !== "message" ? (
            <span
              aria-hidden="true"
              data-control-ui="toast"
              data-control-family="toast"
              data-slot="indicator"
              style={indicatorStyle}
              className="mt-1.5 size-2 shrink-0"
            />
          ) : null}
          <div className="flex min-w-0 flex-1 flex-col gap-0.5">
            {entry.title ? <ToastPrimitive.Title data-control-ui="toast" data-control-family="toast" data-slot="title" /> : null}
            {entry.description ? (
              <ToastPrimitive.Description data-control-ui="toast" data-control-family="toast" data-slot="description" />
            ) : null}
          </div>
          {entry.actionProps ? (
            <ToastPrimitive.Action
              data-control-ui="toast"
              data-control-family="toast"
              data-slot="action"
              style={actionStyle}
              className="shrink-0 cursor-pointer px-2 py-1"
            />
          ) : null}
          <ToastPrimitive.Close
            data-control-ui="toast"
            data-control-family="toast"
            data-slot="close"
            style={closeStyle}
            aria-label="Close"
            className="-mr-1 -mt-1 shrink-0 cursor-pointer p-1"
          >
            <svg viewBox="0 0 16 16" className="size-4" aria-hidden="true" fill="none">
              <path d="M4 4 12 12M12 4 4 12" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" />
            </svg>
          </ToastPrimitive.Close>
        </ToastPrimitive.Content>
      </ToastPrimitive.Root>
    );
  });
}

// Mount once at app root — every toast() lands here, and portalled viewport re-asserts skin scope.
export function Toaster({ className, timeout, limit, rootStyle, indicatorStyle, actionStyle, closeStyle }: ToasterProps) {
  return (
    <ToastPrimitive.Provider toastManager={toastManager} timeout={timeout} limit={limit}>
      <ToastPrimitive.Portal>
        <ToastPrimitive.Viewport
          data-control-ui="toast"
          data-control-family="toast"
          data-slot="viewport"
          data-skin={skinId()}
          data-effects={skinEffects()}
          className={cn("fixed right-4 bottom-4 z-[95] mx-auto w-[calc(100vw-2rem)] sm:right-6 sm:bottom-6 sm:w-[22.5rem]", className)}
        >
          <ToastList rootStyle={rootStyle} indicatorStyle={indicatorStyle} actionStyle={actionStyle} closeStyle={closeStyle} />
        </ToastPrimitive.Viewport>
      </ToastPrimitive.Portal>
    </ToastPrimitive.Provider>
  );
}
